INSERT INTO n_permissions (name, action, module, operation, created_by, version)
            SELECT 'READ_USER_PREFERENCES', 'READ', 'USER_PREFERENCES', 'READ_USER_PREFERENCES', 'system', 0
            WHERE NOT EXISTS (SELECT 1 FROM n_permissions WHERE name = 'READ_USER_PREFERENCES');

